            C#

    using System;
using System.Collections.Generic;

class Program {
    // Recursive function to find all possible permutations
    static void permutations(List<List<int>> res, int[] arr, int idx) {
        if (idx == arr.Length) {
            res.Add(new List<int>(arr));
            return;
        }

        for (int i = idx; i < arr.Length; i++) {
            // Swapping
            int temp = arr[idx];
            arr[idx] = arr[i];
            arr[i] = temp;

            // Recursive call
            permutations(res, arr, idx + 1);

            // Backtracking
            temp = arr[idx];
            arr[idx] = arr[i];
            arr[i] = temp;
        }
    }

    // Function to get the permutations
    static List<List<int>> permuteDist(int[] arr) {
        List<List<int>> res = new List<List<int>>();
        permutations(res, arr, 0);
        return res;
    }

    static void Main() {
        int[] arr = { 1, 2, 3 };
        List<List<int>> res = permuteDist(arr);

        foreach (var x in res) {
            foreach (var y in x) {
                Console.Write(y + " ");
            }
            Console.WriteLine();
        }
    }
}


